DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.pe_match_purchase(uuid,uuid,numeric)'::regprocedure) INTO d; d:=pe_replace_once(d,'INSERT INTO financial_document_payments(document_id,bank_transaction_id,amount,payment_date,method,created_by) VALUES(d.id,t.id,_amount,t.transaction_date,''bank_transfer'',auth.uid());','IF e.original_currency<>''EUR'' THEN UPDATE financial_document_lines SET unit_price_ex_vat=unit_price_ex_vat*(_amount/nullif(d.total_inc_vat,0)) WHERE document_id=d.id; UPDATE financial_documents SET currency=''EUR'',subtotal_ex_vat=round(_amount*(d.subtotal_ex_vat/nullif(d.total_inc_vat,0)),2),vat_amount=_amount-round(_amount*(d.subtotal_ex_vat/nullif(d.total_inc_vat,0)),2),total_inc_vat=_amount WHERE id=d.id; END IF; INSERT INTO financial_document_payments(document_id,bank_transaction_id,amount,payment_date,method,created_by) VALUES(d.id,t.id,_amount,t.transaction_date,''bank_transfer'',auth.uid());'); EXECUTE d; END $$;